instance_norm_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

#define EPS 1e-5

// Kernel prototypes
__global__ void compute_mean_kernel(const float* data, long long total_elements_per_feature, int num_features, float* mean_out);
__global__ void compute_variance_kernel(const float* data, const float* mean_out, float* var_out, long long total_elements_per_feature, int num_features);
__global__ void normalize_kernel(const float* x, float* out, const float* mean, const float* var, long long total_elements, int num_features);

torch::Tensor instance_norm_cuda(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    // Allocate buffers for mean and variance per feature
    auto mean_buf = torch::empty({torch::kFloat}, x.device);
    auto var_buf = torch::empty({torch::kFloat}, x.device);

    // Compute mean per feature
    compute_mean_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        static_cast<long long>(size) / torch::kInt(1),
        torch::kInt(1),
        mean_buf.data_ptr<float>()
    );

    // Compute variance per feature
    compute_variance_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        mean_buf.data_ptr<float>(),
        static_cast<float*>(var_buf.data_ptr<float>()),
        static_cast<long long>(size) / torch::kInt(1),
        torch::kInt(1)
    );

    // Normalize
    normalize_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        mean_buf.data_ptr<float>(),
        var_buf.data_ptr<float>(),
        static_cast<long long>(size),
        torch::kInt(1)
    );

    return out;
}
"""

